const colors={'Alkali metal':'#f6ac92','Alkaline earth metal':'#edcf82','Transition metal':'#93baf8','Post-transition metal':'#aacce0','Metalloid':'#9be1a3','Other nonmetal':'#75dfc1','Halogen':'#c2aff9','Noble gas':'#eda8d3','Lanthanide':'#7ed3e3','Actinide':'#deb3ed'};
const $=s=>document.querySelector(s),table=$('#table'),dialog=$('#detail');let selected=6;
function cell(text,col,row,cls='axis',span=1){const d=document.createElement('div');d.className=cls;d.textContent=text;d.style.gridColumn=`${col} / span ${span}`;d.style.gridRow=row;table.append(d);}
for(let g=1;g<=18;g++)cell(g,g+1,1);
for(let p=1;p<=7;p++)cell(p,1,p+1);
cell('57–71',4,7,'series');cell('89–103',4,8,'series');cell('6 · Lanthanides',1,10,'series',3);cell('7 · Actinides',1,11,'series',3);
const note=document.createElement('div');note.className='table-note';note.innerHTML='<strong>A universe of possibility.</strong><p>Every atom has an identity.<br>Choose a tile and discover what makes it unique.</p>';table.append(note);
for(const e of elements){const b=document.createElement('button');b.className='element';b.dataset.number=e.number;b.style.cssText=`--color:${colors[e.category]};grid-column:${e.col+1};grid-row:${e.row+1}`;b.setAttribute('aria-label',`${e.number}, ${e.name}, ${e.symbol}, ${e.category}`);b.setAttribute('aria-pressed','false');b.tabIndex=e.number===1?0:-1;b.innerHTML=`<span class="number">${e.number}</span><span class="symbol">${e.symbol}</span><span class="name">${e.name}</span>`;b.onclick=()=>show(e.number);b.onkeydown=ev=>navigate(ev,e);table.append(b);}
for(const [name,color]of Object.entries(colors)){$('#category').add(new Option(name,name));const item=document.createElement('span');item.style.setProperty('--color',color);item.innerHTML=`<i></i>${name}`;$('#legend').append(item);}
for(let p=1;p<=7;p++)$('#period').add(new Option(`Period ${p}`,p));
// Region outlines share the table's coordinate system and never intercept tiles.
const blockRegions=[
 {title:'s-block',color:'#ff38bc',numbers:elements.filter(e=>e.group===1||e.group===2).map(e=>e.number),stepped:true},
 {title:'d-block',color:'#ff951f',numbers:elements.filter(e=>e.group>=3&&e.group<=12).map(e=>e.number)},
 {title:'p-block',color:'#497bff',numbers:elements.filter(e=>e.group>=13&&e.number!==2).map(e=>e.number)},
 {title:'f-block series*',color:'#bc64ff',numbers:elements.filter(e=>e.row>=9).map(e=>e.number)},
 {title:'s-block · He',color:'#ff38bc',numbers:[2],top:true}
];
const blockFrames=blockRegions.map(region=>{const frame=document.createElement('div');frame.className='block-outline';frame.style.setProperty('--block-color',region.color);frame.setAttribute('aria-label',region.title);const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('aria-hidden','true');const path=document.createElementNS('http://www.w3.org/2000/svg','path');svg.append(path);const label=document.createElement('span');label.className='block-title';label.textContent=region.title;frame.append(svg,label);table.append(frame);return{region,frame,label,svg,path};});
function layoutBlocks(){const origin=table.getBoundingClientRect();for(const {region,frame,label,svg,path}of blockFrames){const rects=region.numbers.map(n=>table.querySelector(`[data-number="${n}"]`).getBoundingClientRect());const left=Math.min(...rects.map(r=>r.left))-origin.left-3,top=Math.min(...rects.map(r=>r.top))-origin.top-3,right=Math.max(...rects.map(r=>r.right))-origin.left+3,bottom=Math.max(...rects.map(r=>r.bottom))-origin.top+3;const width=right-left,height=bottom-top;Object.assign(frame.style,{left:left+'px',top:top+'px',width:width+'px',height:height+'px'});svg.setAttribute('viewBox',`0 0 ${width} ${height}`);let outline=`M0 0 H${width} V${height} H0 Z`;if(region.stepped){const h=table.querySelector('[data-number="1"]').getBoundingClientRect(),be=table.querySelector('[data-number="4"]').getBoundingClientRect();const stepX=h.right-origin.left+3-left,stepY=be.top-origin.top-3-top;outline=`M0 0 H${stepX} V${stepY} H${width} V${height} H0 Z`;}path.setAttribute('d',outline);label.style.top=region.top?(-top+2)+'px':(height+10)+'px';}}
new ResizeObserver(layoutBlocks).observe(table);document.fonts.ready.then(layoutBlocks);layoutBlocks();
function matches(e){const q=$('#search').value.trim().toLowerCase();const aliases={13:'aluminum',55:'cesium',16:'sulphur'};return(!q||e.name.toLowerCase().includes(q)||e.symbol.toLowerCase()===q||String(e.number)===q||aliases[e.number]?.includes(q))&&(!$('#category').value||e.category===$('#category').value)&&(!$('#period').value||e.period===+$('#period').value);}
function filter(){let count=0;for(const e of elements){const b=table.querySelector(`[data-number="${e.number}"]`),match=matches(e);b.classList.toggle('dim',!match);b.disabled=!match;b.tabIndex=match&&count++===0?0:-1;}$('#count').textContent=`${count} of 118 elements`;$('#empty').hidden=count!==0;}
for(const id of ['search','category','period'])$('#'+id).addEventListener(id==='search'?'input':'change',filter);
$('#reset').onclick=()=>{for(const id of ['search','category','period'])$('#'+id).value='';filter();};
function navigate(ev,e){let target;const available=elements.filter(matches);if(ev.key==='Home')target=available[0];if(ev.key==='End')target=available.at(-1);if(ev.key==='ArrowRight'||ev.key==='ArrowLeft'){const d=ev.key==='ArrowRight'?1:-1;target=available[available.indexOf(e)+d];}if(ev.key==='ArrowDown'||ev.key==='ArrowUp'){const d=ev.key==='ArrowDown'?1:-1;target=available.filter(x=>(x.row-e.row)*d>0).sort((a,b)=>Math.abs(a.row-e.row)-Math.abs(b.row-e.row)||Math.abs(a.col-e.col)-Math.abs(b.col-e.col))[0];}if(target){ev.preventDefault();for(const b of table.querySelectorAll('.element'))b.tabIndex=-1;const b=table.querySelector(`[data-number="${target.number}"]`);b.tabIndex=0;b.focus();}}
function show(n){const e=elements[n-1];selected=n;const f=e.category==='Lanthanide'||e.category==='Actinide',d=e.group>=3&&e.group<=12;const massIsotope=e.mass.startsWith('[');const valenceNote=f?`Outermost-shell convention: ${e.valence} electrons (${n===103?'7s²7p¹':e.period+'s²'}). The f and d electrons may also take part in bonding, so this is not a universal bonding-electron count.`:d?`Formal s + d convention: ${e.valence} electrons. This includes the outer s and preceding d subshells, not just the outermost shell. The number involved in bonding varies by compound; this is not an oxidation state.`:`Outermost-shell convention: ${e.valence} electrons.${n>112?' This count follows the expected main-group configuration; superheavy chemistry is not fully established.':''}`;
$('#profile').style.setProperty('--color',colors[e.category]);$('#profile').innerHTML=`<div class="identity"><div class="big-symbol"><span>${e.number}</span><strong>${e.symbol}</strong></div><div><h2 id="element-name">${e.name}</h2><p>${e.category}</p></div></div><dl class="properties"><div class="property"><dt>Atomic number</dt><dd>${e.number}</dd><small>Protons in the nucleus</small></div><div class="property"><dt>Atomic mass${massIsotope?' / isotope':''}</dt><dd>${e.mass}${massIsotope?'':' u'}</dd><small>${massIsotope?'Isotope mass number':`Uncertainty: ± ${e.uncertainty} u`}</small></div><div class="property"><dt>Period</dt><dd>${e.period}</dd><small>Horizontal row of the table</small></div><div class="property"><dt>Electrons</dt><dd>${e.number}</dd><small>Neutral atom: equals atomic number</small></div><div class="property"><dt>Valence electrons</dt><dd>${e.valence}</dd><small>${f?'Outermost shell':d?'Formal s + d count':'Outermost shell'}</small></div><div class="property"><dt>Chemical symbol</dt><dd>${e.symbol}</dd><small>The element’s shorthand</small></div></dl><p class="note">${valenceNote}</p><p class="note">${massIsotope?'Square brackets give protons + neutrons for a selected isotope (IUPAC 2022). This element has no standard atomic weight. The number is not an exact mass in u.':'The atomic mass shown is an average for normal terrestrial materials, based on CIAAW’s abridged standard atomic weight. Different isotopes and samples can have different masses.'}</p><a class="source-link" target="_blank" rel="noreferrer" href="https://periodic-table.rsc.org/element/${n}/${e.name.toLowerCase()}">Explore ${e.name} at the Royal Society of Chemistry</a>`;
$('#previous').disabled=n===1;$('#next').disabled=n===118;for(const b of table.querySelectorAll('.element'))b.setAttribute('aria-pressed',String(+b.dataset.number===n));if(!dialog.open)dialog.showModal();}
$('#close').onclick=()=>dialog.close();$('#previous').onclick=()=>show(selected-1);$('#next').onclick=()=>show(selected+1);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'show_element',description:'Open the element detail panel for an atomic number.',inputSchema:{type:'object',properties:{atomicNumber:{type:'integer',minimum:1,maximum:118}},required:['atomicNumber'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!Number.isInteger(input.atomicNumber)||input.atomicNumber<1||input.atomicNumber>118)throw Error('Atomic number must be an integer from 1 to 118.');show(input.atomicNumber);return elements[input.atomicNumber-1];}})).catch(()=>{});}catch{}}
